mapper.delete:
DELETE FROM dcr03_org_auth
 WHERE dcr03_class_tree_id = #{classTreeId}
   AND dcr03_org_code_id   = #{orgCodeId}
   AND dcr03_org_auth_id NOT IN ( SELECT MAX(x.dcr03_org_auth_id) FROM dcr03_org_auth x
                                   WHERE x.dcr03_class_tree_id = #{classTreeId} AND x.dcr03_org_code_id = #{orgCodeId} )

mapper.update:
WITH upsert AS (
    UPDATE dcr03_org_auth
       SET dcr03_retrieve_yn = #{retrieveYn}
         , dcr03_update_yn   = #{updateYn}
     WHERE dcr03_org_code_id   = #{orgCodeId}
       AND dcr03_class_tree_id = #{classTreeId}
    RETURNING *
)
INSERT INTO dcr03_org_auth (dcr03_org_auth_id, dcr03_org_code_id, dcr03_class_tree_id, dcr03_retrieve_yn, dcr03_update_yn)
SELECT f_create_seq(), #{orgCodeId}, #{classTreeId}, #{retrieveYn}, #{updateYn}
 WHERE NOT EXISTS ( SELECT * FROM upsert )
